const upsertAuthAttempt = `-- name: UpsertAuthAttempt :exec
INSERT INTO auth_attempt (tenant_id, subject_hash, failures, last_failure_at, locked_until)
VALUES (
  current_tenant_id(), $1, $2,
  $3, $4
)
ON CONFLICT (tenant_id, subject_hash) DO UPDATE
SET failures        = EXCLUDED.failures,
    last_failure_at = EXCLUDED.last_failure_at,
    locked_until    = EXCLUDED.locked_until
`

type UpsertAuthAttemptParams struct {
	SubjectHash   []byte
	Failures      int32
	LastFailureAt pgtype.Timestamptz
	LockedUntil   pgtype.Timestamptz
}

// The counter and the moment are computed by the caller from what it read: the delay curve is the
// domain's, and a statement that computed it would be policy in SQL.
func (q *Queries) UpsertAuthAttempt(ctx context.Context, arg UpsertAuthAttemptParams) error {
	_, err := q.db.Exec(ctx, upsertAuthAttempt,
		arg.SubjectHash,
		arg.Failures,
		arg.LastFailureAt,
		arg.LockedUntil,
	)
	return err
}

const upsertMfaEnrollment = `-- name: UpsertMfaEnrollment :execrows

INSERT INTO account_mfa
  (account_id, tenant_id, secret_enc, secret_key_id, created_at, updated_at)
VALUES (
  $1, current_tenant_id(), $2,
  $3, $4, $4
)
ON CONFLICT (account_id) DO UPDATE
SET secret_enc = EXCLUDED.secret_enc,
    secret_key_id = EXCLUDED.secret_key_id,
    confirmed_at = NULL,
    last_step = NULL,
    updated_at = EXCLUDED.updated_at
WHERE account_mfa.confirmed_at IS NULL
`

type UpsertMfaEnrollmentParams struct {
	AccountID   pgtype.UUID
	SecretEnc   []byte
	SecretKeyID string
	Now         pgtype.Timestamptz
}

// ============================ The second factor (H-02) ============================
// A fresh enrolment, or the replacement of an unconfirmed one. An armed enrolment matches
// nothing - zero rows is the "disable first, with the password" refusal - so a stolen session
// cannot quietly swap the secret out from under the real authenticator.
func (q *Queries) UpsertMfaEnrollment(ctx context.Context, arg UpsertMfaEnrollmentParams) (int64, error) {
	result, err := q.db.Exec(ctx, upsertMfaEnrollment,
		arg.AccountID,
		arg.SecretEnc,
		arg.SecretKeyID,
		arg.Now,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
